import{_ as n,C as i,c as d,o as h,a3 as a,G as r,j as t,a as s}from"./chunks/framework.Dokpd4od.js";const S=JSON.parse('{"title":"Session report","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/reporting/session-report.md","filePath":"master/sales/point-of-sale/reporting/session-report.md","lastUpdated":1793074831000}'),l={name:"master/sales/point-of-sale/reporting/session-report.md"};function p(c,e,m,u,f,g){const o=i("ImagePopup");return h(),d("div",null,[e[0]||(e[0]=a('<h1 id="session-report" tabindex="-1">Session report <a class="header-anchor" href="#session-report" aria-label="Permalink to &quot;Session report&quot;">​</a></h1><p>The Session report shows the result of one session: how many orders it had, how customers paid and how the cash drawer looked. Use it when you close a session, or when you need to find out why the cash did not match.</p><blockquote><p><strong>In simple words:</strong> Choose a session. The page shows its sales, its payments and whether the drawer balanced.</p></blockquote><h2 id="open-the-report" tabindex="-1">Open the report <a class="header-anchor" href="#open-the-report" aria-label="Permalink to &quot;Open the report&quot;">​</a></h2><ol><li>Go to <code>Point of Sale → Reporting → Session Report</code>.</li><li>Click the <strong>Session</strong> list. It shows the 50 latest sessions, newest first, in the form <code>TNE/SESSION/00002</code> followed by the register name.</li><li>Pick a session.</li></ol>',5)),r(o,{src:"/images1/pos/session_report_select.png",alt:"Session Report with the Session list open showing TNE/SESSION/00002 TechNest Electronics selected"}),e[1]||(e[1]=t("p",null,[s("Until you pick one, the page shows "),t("strong",null,"No session selected"),s(" and the hint "),t("strong",null,"Pick a session to see its report.")],-1)),e[2]||(e[2]=t("h2",{id:"read-the-report",tabindex:"-1"},[s("Read the report "),t("a",{class:"header-anchor",href:"#read-the-report","aria-label":'Permalink to "Read the report"'},"​")],-1)),r(o,{src:"/images1/pos/session_report_result.png",alt:"Session Report for TNE/SESSION/00002 showing Orders 3, Refunds 1, Total 6,597.00, Payments Cash 6,597.00 and Cash Drawer Opening 1,750.00, Cash In/Out -500.00, Expected 7,847.00, Difference 0.00"}),e[3]||(e[3]=a('<h3 id="orders" tabindex="-1">Orders <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;Orders&quot;">​</a></h3><ul><li><strong><em>Orders:</em></strong> The number of settled orders in the session.</li><li><strong><em>Refunds:</em></strong> How many of them are refunds (negative total).</li><li><strong><em>Total:</em></strong> The total of all those orders.</li></ul><h3 id="payments" tabindex="-1">Payments <a class="header-anchor" href="#payments" aria-label="Permalink to &quot;Payments&quot;">​</a></h3><p>One line for each payment method used in the session, with the amount. When nothing was paid, the page reads <strong>No payments recorded.</strong></p><h3 id="cash-drawer" tabindex="-1">Cash Drawer <a class="header-anchor" href="#cash-drawer" aria-label="Permalink to &quot;Cash Drawer&quot;">​</a></h3><ul><li><strong><em>Opening:</em></strong> The cash you counted when you opened the register.</li><li><strong><em>Cash In/Out:</em></strong> The net of cash moves. A cash out shows as a negative number.</li><li><strong><em>Expected:</em></strong> The cash the drawer should hold. It is the opening amount plus cash payments plus the cash in/out net.</li><li><strong><em>Difference:</em></strong> Counted cash minus expected cash. It shows a dash until you close the session.</li></ul><p>A difference of 0.00 means the drawer balanced. A negative number means cash is missing. A positive number means there is extra cash.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Session TNE/SESSION/00002 of TechNest Electronics:</p><table tabindex="0"><thead><tr><th>Section</th><th>Line</th><th>Value</th></tr></thead><tbody><tr><td>Orders</td><td>Orders</td><td>3</td></tr><tr><td>Orders</td><td>Refunds</td><td>1</td></tr><tr><td>Orders</td><td>Total</td><td>6,597.00</td></tr><tr><td>Payments</td><td>Cash</td><td>6,597.00</td></tr><tr><td>Cash Drawer</td><td>Opening</td><td>1,750.00</td></tr><tr><td>Cash Drawer</td><td>Cash In/Out</td><td>-500.00</td></tr><tr><td>Cash Drawer</td><td>Expected</td><td>7,847.00</td></tr><tr><td>Cash Drawer</td><td>Difference</td><td>0.00</td></tr></tbody></table><p>The cashier opened with 1,750.00, took 6,597.00 in net cash and paid out 500.00 for a courier (&quot;Paid courier for same day delivery&quot;). The drawer should hold 7,847.00. The closing count was 7,847.00, so the difference is 0.00.</p><p>Pick a session without sales, such as SRK/SESSION/00002, and every number is zero.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A cash difference stays in the report after closing. Check the cash in and out entries of the session to find the reason.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Reporting overview</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li><li><a href="./../sessions/cash-in-and-out.html">Cash in and out</a></li><li><a href="./sales-details.html">Sales details</a></li></ul>',15))])}const b=n(l,[["render",p]]);export{S as __pageData,b as default};
